#!/bin/bash
# Auto-generated by bootstrap-new-mac.sh -- runs at every login via the
# com.example.mount-ollama-models LaunchAgent below.
SMB_HOST="unraid-host.local"
SMB_SHARE="data"
SMB_USER="user"
# macOS mounts SMB shares at /Volumes/<share-name> by default -- a custom
# mount point name (the old "/Volumes/LLM Models") just causes mount_smbfs
# to silently fail with "File exists" once the share is already mounted
# under its real name by something else (Finder, another login, etc.),
# leaving OLLAMA_MODELS pointed at an empty/local directory instead of the
# real network share. Use the share's actual mount point instead.
MOUNT_POINT="/Volumes/$SMB_SHARE"
OLLAMA_MODELS_SUBDIR="ollama-models"

if ! mount | grep -q "on $MOUNT_POINT "; then
  mkdir -p "$MOUNT_POINT"
  SMB_PASS=$(security find-internet-password -a "$SMB_USER" -s "$SMB_HOST" -w 2>/dev/null)
  if [ -n "$SMB_PASS" ]; then
    mount_smbfs "//${SMB_USER}:${SMB_PASS}@${SMB_HOST}/${SMB_SHARE}" "$MOUNT_POINT" >/dev/null 2>&1
  fi
fi

# Real incident 2026-08-22: this used to run setenv+restart unconditionally,
# even when the mount above failed. That pointed OLLAMA_MODELS at a path
# that doesn't exist, which then made Ollama fail to start at all (`mkdir
# /Volumes/data: permission denied`) on every restart until the env var was
# manually unset -- and the restart itself killed an in-flight dispatch mid
# run. Only touch OLLAMA_MODELS/restart Ollama if the mount is actually up,
# and skip the restart entirely if the value isn't even changing (Ollama may
# already be serving real work -- don't disrupt it for a no-op).
#
# ── CHANGED 2026-08-23: SERVE FROM LOCAL, KEEP UNRAID AS THE STORE ──────────
# This used to point OLLAMA_MODELS at the SHARE, so Ollama read every model
# straight off SMB. Measured that day: SMB 299 MB/s versus local SSD 2927 MB/s,
# and far worse under memory pressure -- qwen3-coder-next (51.7GB) could not
# finish loading inside a 900s warmup budget and killed a run outright. The
# worker's own note says it plainly: Ollama's model-load path over SMB hangs
# indefinitely, while a plain file COPY from the same share does not.
#
# So the share stays mounted -- it is the model STORE, and bakeoff-v8-stage.py
# copies from it -- but Ollama serves from the local cache. Pull what is needed,
# evict when done.
#
# The mount check is retained deliberately: if the share is down there is
# nothing to stage FROM, and that is worth surfacing rather than silently
# serving whatever happens to be cached.
if mount | grep -q "on $MOUNT_POINT "; then
  # ── CHANGED 2026-09-01: THE LOCAL STORE MOVED TO NVMe ────────────────────
  # This hardcoded $HOME/.ollama/models, correct until the 4TB NVMe landed and
  # the real store became /Volumes/NVMe-Models/ollama-models (222G). After that
  # move this agent, ticking every 60s, kept resetting OLLAMA_MODELS back to
  # ~/.ollama/models -- now EMPTY -- and running `brew services restart ollama`,
  # which regenerates the LaunchAgent plist from that value and makes it
  # durable. Ollama then served ZERO models and every dispatch died in
  # ensure_model_cached with "not found in SMB source". It killed a full 10-arm
  # bake-off on 2026-09-01: every arm failed identically, which reads exactly
  # like model incapacity and is nothing of the kind.
  NEW_MODELS_PATH="/Volumes/NVMe-Models/ollama-models"
  # Only ever repoint at a store that actually HAS models. Pointing Ollama at an
  # empty directory is worse than leaving it alone -- it serves nothing, and the
  # restart bakes the bad value into the plist. If the NVMe is not mounted, do
  # nothing and let whatever is currently serving keep serving.
  if [ -d "$NEW_MODELS_PATH/manifests" ]; then
    if [ "$(launchctl getenv OLLAMA_MODELS 2>/dev/null)" != "$NEW_MODELS_PATH" ]; then
      launchctl setenv OLLAMA_MODELS "$NEW_MODELS_PATH"
      /opt/homebrew/bin/brew services restart ollama 2>/dev/null
    fi
  fi
fi
